WITH filtered_employees AS (SELECT *, LAST_DAY(hire_date) AS hire_date_month_end FROM employees WHERE NOT is_remote AND salary >= 91000), employees_stats AS (SELECT MONTH(hire_date) AS hire_month, ROUND(STDDEV(salary), 2) AS stddev_salary, ROUND((100 * SUM(CASE WHEN level = 'L5' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l5 FROM filtered_employees GROUP BY MONTH(hire_date)) SELECT * FROM employees_stats ORDER BY stddev_salary;
